298	// detectRemoteOnlyArchives discovers archived generation refs on the remote
299	// that don't exist locally. Returns them sorted ascending (oldest first).
300	func detectRemoteOnlyArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
301		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
302		defer cancel()
303	
304		output, err := remote.LsRemote(ctx, target, paths.V2FullRefPrefix+"*")
305		if err != nil {
306			return nil, fmt.Errorf("ls-remote failed: %w", err)
307		}
308	
309		var remoteOnly []string
310		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
311			if line == "" {
312				continue
313			}
314			parts := strings.Fields(line)
315			if len(parts) < 2 {
316				continue
317			}
318			refName := parts[1]
319			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
320			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
321				continue
322			}
323			// Only check for existence, not hash equality. A locally-present archive
324			// could be stale if another machine updated it via rotation conflict recovery,
325			// but that's unlikely and the checkpoints are still on /main regardless.
326			if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
327				remoteOnly = append(remoteOnly, suffix)
328			}
329		}
330	
331		sort.Strings(remoteOnly)
332		return remoteOnly, nil
333	}
