491	// pushV2Refs pushes v2 checkpoint refs to the target.
492	// Pushes /main, /full/current, and the latest archived generation (if any) in
493	// one git push. Older archived generations are immutable and were pushed when created.
494	func pushV2Refs(ctx context.Context, target string) {
495		refs := v2RefsToPush(ctx)
496		if len(refs) == 0 {
497			return
498		}
499	
500		fmt.Fprintln(os.Stderr, "[entire] Syncing and pushing v2 checkpoints...")
501		fmt.Fprintf(os.Stderr, "[entire] Pushing %s...\n", strings.Join(shortRefNames(refs), ", "))
502	
503		results := pushV2RefsWithRecovery(ctx, target, refs)
504		var failures []error
505		var successfulRefs []plumbing.ReferenceName
506		pushedContent := false
507		for _, result := range results {
508			if result.err != nil {
509				failures = append(failures, result.err)
510				continue
511			}
512			successfulRefs = append(successfulRefs, result.refName)
513			if !result.result.upToDate {
514				pushedContent = true
515			}
516		}
517	
518		if len(failures) > 0 {
519			printV2PartialPushResult(os.Stderr, successfulRefs, failures)
520			printCheckpointRemoteHint(target)
521			if pushedContent {
522				printSettingsCommitHint(ctx, target)
523			}
524			printCheckpointsV2MigrationHint(ctx)
525			return
526		}
527	
528		fmt.Fprintln(os.Stderr, "[entire] All v2 checkpoints pushed")
529		if pushedContent {
530			printSettingsCommitHint(ctx, target)
531		}
532		printCheckpointsV2MigrationHint(ctx)
533	}
